async def _ensure_workflow_context():
    context_manager = GriptapeNodes.ContextManager()
    if not context_manager.has_current_flow():
        top_level_flow_request = GetTopLevelFlowRequest()
        top_level_flow_result = await GriptapeNodes.ahandle_request(top_level_flow_request)
        if isinstance(top_level_flow_result, GetTopLevelFlowResultSuccess) and top_level_flow_result.flow_name is not None:
            flow_manager = GriptapeNodes.FlowManager()
            flow_obj = flow_manager.get_flow_by_name(top_level_flow_result.flow_name)
            context_manager.push_flow(flow_obj)

def execute_workflow(input: dict, *, workflow_executor: WorkflowExecutor | None=None, **kwargs: Any) -> dict | None:
    return asyncio.run(aexecute_workflow(input=input, workflow_executor=workflow_executor, **kwargs))

async def aexecute_workflow(input: dict, *, workflow_executor: WorkflowExecutor | None=None, **kwargs: Any) -> dict | None:
    if workflow_executor is None:
        workflow_executor = LocalWorkflowExecutor(skip_library_loading=True, workflows_to_register=[__file__], **kwargs)
    async with workflow_executor as executor:
        await build_workflow()
        await _ensure_workflow_context()
        await executor.arun(flow_input=input, **kwargs)
    return executor.output

if __name__ == '__main__':
    logging.basicConfig(level=logging.INFO)
    parser = argparse.ArgumentParser()
    LocalWorkflowExecutor.add_cli_arguments(parser)
    parser.add_argument('--json-input', default=None, help='JSON string containing parameter values. Takes precedence over individual parameter arguments if provided.')
    parser.add_argument('--exec_out', dest='exec_out', default=None, help='Connection to the next node in the execution chain')
    parser.add_argument('--editing_instruction', dest='editing_instruction', default=None, help='New parameter')
    parser.add_argument('--improveprompt', dest='improveprompt', default=None, help='Enter boolean (true/false) for improveprompt.')
    parser.add_argument('--model_1', dest='model_1', default=None, help='Select the video model to route to.')
    parser.add_argument('--aspect_ratio', dest='aspect_ratio', default=None, help='Shared aspect ratio for Veo 3 and Kling (options limited to values both support).')
    parser.add_argument('--resolution_veo3', dest='resolution_veo3', default=None, help='Veo 3 output resolution (1080p only supports 8 second duration).')
    parser.add_argument('--duration_veo3', dest='duration_veo3', default=None, help='Veo 3 video duration in seconds.')
    parser.add_argument('--duration_kling', dest='duration_kling', default=None, help='Kling video duration in seconds (3-15).')
    parser.add_argument('--start_frame', dest='start_frame', default=None, help='Start frame image for the video.')
    parser.add_argument('--end_frame', dest='end_frame', default=None, help='End frame image for the video.')
    args = parser.parse_args()
    flow_input = {}
    if args.json_input is not None:
        flow_input = json.loads(args.json_input)
    if args.json_input is None:
        if 'Start Flow' not in flow_input:
            flow_input['Start Flow'] = {}
        if args.exec_out is not None:
            flow_input['Start Flow']['exec_out'] = args.exec_out
        if args.editing_instruction is not None:
            flow_input['Start Flow']['editing_instruction'] = args.editing_instruction
        if args.improveprompt is not None:
            flow_input['Start Flow']['improveprompt'] = args.improveprompt
        if args.model_1 is not None:
            flow_input['Start Flow']['model_1'] = args.model_1
        if args.aspect_ratio is not None:
            flow_input['Start Flow']['aspect_ratio'] = args.aspect_ratio
        if args.resolution_veo3 is not None:
            flow_input['Start Flow']['resolution_veo3'] = args.resolution_veo3
        if args.duration_veo3 is not None:
            flow_input['Start Flow']['duration_veo3'] = args.duration_veo3
        if args.duration_kling is not None:
            flow_input['Start Flow']['duration_kling'] = args.duration_kling
        if args.start_frame is not None:
            flow_input['Start Flow']['start_frame'] = args.start_frame
        if args.end_frame is not None:
            flow_input['Start Flow']['end_frame'] = args.end_frame
    executor = LocalWorkflowExecutor.from_cli_args(args, skip_library_loading=True, workflows_to_register=[__file__])
    workflow_output = execute_workflow(input=flow_input, workflow_executor=executor)
    print(workflow_output)
